}

// getGenerationAnnotation will return the generation annotation on the
// vmi as a string pointer. The string pointer will be nil if the annotation is
// not found (including when the annotations map is empty).
func getGenerationAnnotation(vmi *virtv1.VirtualMachineInstance) (*string, error) {
	if vmi == nil {
		return nil, errors.New("received nil pointer for vmi")
	}

	currentGenerationAnnotation, found := vmi.Annotations[virtv1.VirtualMachineGenerationAnnotation]
	if found {
		return &currentGenerationAnnotation, nil
	}

	return nil, nil
}

// patchVmGenerationAnnotationOnVmi patches the vmi in the API to set the
// VirtualMachineGenerationAnnotation to the given generation as a decimal
// string. The patched vmi is returned.
func (c *Controller) patchVmGenerationAnnotationOnVmi(generation int64, vmi *virtv1.VirtualMachineInstance) (*virtv1.VirtualMachineInstance, error) {
	newVmi := vmi.DeepCopy()
	setGenerationAnnotationOnVmi(generation, newVmi)

	patchSet := patch.New()
	if vmi.Annotations == nil {
		patchSet.AddOption(patch.WithAdd("/metadata/annotations", newVmi.Annotations))
	} else {
		patchSet.AddOption(
			patch.WithTest("/metadata/annotations", vmi.Annotations),
			patch.WithReplace("/metadata/annotations", newVmi.Annotations),
		)
	}

	patchBytes, err := patchSet.GeneratePayload()
	if err != nil {
		return vmi, err
	}

	patchedVMI, err := c.clientset.VirtualMachineInstance(vmi.Namespace).Patch(context.Background(), vmi.Name, types.JSONPatchType, patchBytes, v1.PatchOptions{})
	if err != nil {
		return vmi, err
	}

	return patchedVMI, nil
}

// getControllerRevision attempts to get the controller revision by name and
// namespace. It will return (nil, nil) if the controller revision is not found.
func (c *Controller) getControllerRevision(namespace string, name string) (*appsv1.ControllerRevision, error) {
	cr, err := c.clientset.AppsV1().ControllerRevisions(namespace).Get(context.Background(), name, metav1.GetOptions{})
	if err != nil {
		if apiErrors.IsNotFound(err) {
			return nil, nil
		}
		return nil, err
	}

	return cr, nil
}

// conditionallyBumpGenerationAnnotationOnVmi will check whether the generation
// annotation needs to be bumped on the vmi, and then bump that annotation if
// needed. The checks are:
//  1. If the generation has not changed, do not bump.
//  2. Only bump if the template specs are the same.
//
// Note that if only the run strategy of the VM has changed (a non-template
// change), the generation annotation will still be bumped, since this does not
// affect the VMI.
func (c *Controller) conditionallyBumpGenerationAnnotationOnVmi(vm *virtv1.VirtualMachine, vmi *virtv1.VirtualMachineInstance) (*virtv1.VirtualMachineInstance, error) {
	if vmi == nil || vm == nil {
		return vmi, nil
	}

	// If this is an old vmi created before a controller update, then the
	// annotation may not exist. In that case, continue on as if the generation
	// annotation needs to be bumped.
	currentGeneration, err := getGenerationAnnotation(vmi)
	if err != nil {
		return vmi, err
	}
	if currentGeneration != nil && *currentGeneration == strconv.FormatInt(vm.Generation, 10) {
		return vmi, nil
	}

	currentRevision, err := c.getControllerRevision(vmi.Namespace, vmi.Status.VirtualMachineRevisionName)
	if currentRevision == nil || err != nil {
		return vmi, err
	}

	revisionData := &VirtualMachineRevisionData{}
	if err = json.Unmarshal(currentRevision.Data.Raw, revisionData); err != nil {
		return vmi, err
	}

	// If the template specs are the same, we can safely bump the annotation.
	if equality.Semantic.DeepEqual(revisionData.Spec.Template, vm.Spec.Template) {
		vmi, err = c.patchVmGenerationAnnotationOnVmi(vm.Generation, vmi)
		if err != nil {
			return vmi, err
		}
	}

	return vmi, nil
}

