2310	// annotation needs to be bumped on the vmi, and then bump that annotation if
2311	// needed. The checks are:
2312	//  1. If the generation has not changed, do not bump.
2313	//  2. Only bump if the template specs are the same.
2314	//
2315	// Note that if only the run strategy of the VM has changed (a non-template
2316	// change), the generation annotation will still be bumped, since this does not
2317	// affect the VMI.
2318	func (c *Controller) conditionallyBumpGenerationAnnotationOnVmi(vm *virtv1.VirtualMachine, vmi *virtv1.VirtualMachineInstance) (*virtv1.VirtualMachineInstance, error) {
2319		if vmi == nil || vm == nil {
2320			return vmi, nil
2321		}
2322	
2323		// If this is an old vmi created before a controller update, then the
2324		// annotation may not exist. In that case, continue on as if the generation
2325		// annotation needs to be bumped.
2326		currentGeneration, err := getGenerationAnnotation(vmi)
2327		if err != nil {
2328			return vmi, err
2329		}
2330		if currentGeneration != nil && *currentGeneration == strconv.FormatInt(vm.Generation, 10) {
2331			return vmi, nil
2332		}
2333	
2334		currentRevision, err := c.getControllerRevision(vmi.Namespace, vmi.Status.VirtualMachineRevisionName)
2335		if currentRevision == nil || err != nil {
2336			return vmi, err
2337		}
2338	
2339		revisionData := &VirtualMachineRevisionData{}
2340		if err = json.Unmarshal(currentRevision.Data.Raw, revisionData); err != nil {
2341			return vmi, err
2342		}
2343	
2344		// If the template specs are the same, we can safely bump the annotation.
2345		if equality.Semantic.DeepEqual(revisionData.Spec.Template, vm.Spec.Template) {
2346			vmi, err = c.patchVmGenerationAnnotationOnVmi(vm.Generation, vmi)
2347			if err != nil {
2348				return vmi, err
2349			}
2350		}
2351	
2352		return vmi, nil
2353	}
